public protocol AnalyticsEvent: Sendable, Encodable {
    static var name: String { get }
    static var schemaVersion: Int { get }
}

public final class Analytics: Sendable {
    private let pipeline: EventPipeline          // actor: buffer -> disk -> uploader
    public func track<E: AnalyticsEvent>(_ event: E) {
        let envelope = Envelope(id: UUID(), name: E.name, version: E.schemaVersion,
                                timestamp: .now, payload: event)
        Task { await pipeline.enqueue(envelope) }   // returns immediately
    }
}
